import 'package:flutter/material.dart';
import 'package:lazerus_core/lazerus_core.dart';

import '../../../../../core/macros/sinks/lighting_target_sink.dart';
import '../../../../../core/macros/templates/macro_template_transformer.dart';
import '../../../../debug/application/debug_devices_controller.dart';
import '../../../../devices/presentation/device_control_card.dart';
import '../macro_editor_node_module.dart';

final class LightingTargetMacroEditorNodeModule extends MacroEditorNodeModule
    implements MacroEditorBindingModule {
  static const _templateTransformer = MacroTemplateTransformer();

  @override
  String get kind => lightingTargetSinkKind;

  @override
  Iterable<MacroEditorPaletteEntry> paletteEntries(
    MacroEditorNodePresentationState state,
  ) sync* {
    for (final device in state.devices) {
      final available = device.capabilities != null;
      yield MacroEditorPaletteEntry(
        id: 'palette.device.${device.appDeviceId}',
        moduleKind: kind,
        section: MacroEditorPaletteSection.devices,
        icon: Icons.lightbulb_outline,
        title: device.displayName,
        subtitle: available
            ? '${device.status.name} · drag to add inputs'
            : 'Connect to load capabilities',
        enabled: available,
        payload: device,
      );
    }
  }

  @override
  MacroNode? createNode(
    MacroEditorPaletteEntry entry, {
    required MacroEditorNewId newId,
  }) {
    final device = entry.payload;
    if (device is! DebugDevice) return null;
    final parameters = _parametersForCapabilities(device.capabilities);
    if (parameters.isEmpty) return null;
    return _newTargetNode(
      id: newId(),
      targetId: device.appDeviceId,
      displayName: device.displayName,
      parameters: parameters,
    );
  }

  @override
  Widget buildInspector(
    BuildContext context,
    MacroEditorNodeViewContext nodeContext,
  ) {
    try {
      final configuration = LightingTargetNodeConfiguration.fromNode(
        nodeContext.node,
      );
      if (_templateTransformer.isMacroTemplateDevicePlaceholderId(
        configuration.targetId,
      )) {
        return _placeholderInspector(nodeContext, configuration);
      }
      final device = nodeContext.state.devicesById[configuration.targetId];
      if (device == null) {
        return _fallbackInspector(
          nodeContext,
          'Девайс більше не доступний. Повторіть scan або видаліть target node.',
        );
      }
      final inputDrivenFeatures = _inputDrivenFeatures(nodeContext);
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: <Widget>[
          MacroEditorNodeInspectorCard(
            icon: Icons.tune_outlined,
            title: 'Device controls',
            enabled: nodeContext.state.enabled,
            onRemove: nodeContext.removeNode,
            child: const Text(
              'Ручні значення застосовуються, доки відповідний input не надіслав значення.',
            ),
          ),
          const SizedBox(height: 8),
          DeviceControlCard(
            key: ValueKey<String>(
              'macro-device-control-${nodeContext.node.id}',
            ),
            appDeviceId: device.appDeviceId,
            deviceName: device.displayName,
            inputDrivenFeatures: inputDrivenFeatures,
            inputDrivenMessage: _inputDrivenMessage(inputDrivenFeatures),
          ),
        ],
      );
    } on FormatException catch (error) {
      return MacroEditorNodeErrorCard(
        message: 'Device target configuration needs repair: $error',
      );
    }
  }

  @override
  double cardBodyHeight(MacroNode node) {
    try {
      final configuration = LightingTargetNodeConfiguration.fromNode(node);
      return _templateTransformer.isMacroTemplateDevicePlaceholderId(
            configuration.targetId,
          )
          ? 34
          : 0;
    } on FormatException {
      return 0;
    }
  }

  @override
  Widget? buildCardBody(
    BuildContext context,
    MacroEditorNodeViewContext nodeContext,
  ) {
    try {
      final configuration = LightingTargetNodeConfiguration.fromNode(
        nodeContext.node,
      );
      if (!_templateTransformer.isMacroTemplateDevicePlaceholderId(
        configuration.targetId,
      )) {
        return null;
      }
      return Row(
        children: <Widget>[
          Icon(
            Icons.device_unknown_outlined,
            size: 18,
            color: Theme.of(context).colorScheme.error,
          ),
          const SizedBox(width: 6),
          const Expanded(
            child: Text(
              'Натисніть, щоб обрати девайс',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
          ),
        ],
      );
    } on FormatException {
      return null;
    }
  }

  @override
  String titleFor(MacroNode node) {
    try {
      final configuration = LightingTargetNodeConfiguration.fromNode(node);
      if (_templateTransformer.isMacroTemplateDevicePlaceholderId(
        configuration.targetId,
      )) {
        return _templateTransformer.placeholderLabelFor(configuration.targetId);
      }
    } on FormatException {
      // Let the generic error inspector describe malformed persisted config.
    }
    return super.titleFor(node);
  }

  @override
  Iterable<MacroTargetBinding> deriveTargetBindings(MacroGraph graph) {
    final targetsByInputPort = <String, _TargetInput>{};
    for (final node in graph.nodes) {
      if (!supports(node)) continue;
      try {
        final configuration = LightingTargetNodeConfiguration.fromNode(node);
        for (final parameter in configuration.parameters) {
          targetsByInputPort['${node.id}.${parameter.name}'] = _TargetInput(
            targetId: configuration.targetId,
            parameter: parameter,
          );
        }
      } on FormatException {
        // Keep malformed persisted nodes repairable; validation reports them.
      }
    }
    return graph.edges.map((edge) {
      final target = targetsByInputPort[edge.toPortId];
      if (target == null) return null;
      return MacroTargetBinding(
        id: 'target-edge-${edge.id}',
        sourcePortId: edge.fromPortId,
        targetId: target.targetId,
        parameter: target.parameter,
      );
    }).whereType<MacroTargetBinding>();
  }

  @override
  MacroGraph migrateLegacyBindings(
    MacroGraph graph, {
    required MacroEditorNewId newId,
  }) {
    final existingKeys = deriveTargetBindings(graph).map(_bindingKey).toSet();
    final legacyBindings = graph.targetBindings
        .where((binding) => !existingKeys.contains(_bindingKey(binding)))
        .toList(growable: false);
    if (legacyBindings.isEmpty) return graph;

    final nodes = <MacroNode>[...graph.nodes];
    final edges = <MacroEdge>[...graph.edges];
    final positions = <String, MacroEditorPosition>{...graph.editorPositions};
    for (final binding in legacyBindings) {
      MacroNode? targetNode;
      for (final candidate in nodes) {
        if (!supports(candidate)) continue;
        try {
          final configuration = LightingTargetNodeConfiguration.fromNode(
            candidate,
          );
          final inputId = '${candidate.id}.${binding.parameter.name}';
          if (configuration.targetId == binding.targetId &&
              configuration.parameters.contains(binding.parameter) &&
              !edges.any((edge) => edge.toPortId == inputId)) {
            targetNode = candidate;
            break;
          }
        } on FormatException {
          // Preserve the invalid saved node unchanged for repair.
        }
      }
      targetNode ??= _newTargetNode(
        id: newId(),
        targetId: binding.targetId,
        displayName: 'Device ${binding.targetId}',
        parameters: <MacroTargetParameter>[binding.parameter],
      );
      if (!nodes.any((node) => node.id == targetNode!.id)) {
        nodes.add(targetNode);
        positions[targetNode.id] = MacroEditorPosition(
          x: 600 + ((nodes.length % 2) * 250),
          y: 80 + ((nodes.length ~/ 2) * 180),
        );
      }
      edges.add(
        MacroEdge(
          id: newId(),
          fromPortId: binding.sourcePortId,
          toPortId: '${targetNode.id}.${binding.parameter.name}',
        ),
      );
    }
    return graph.copyWith(
      nodes: nodes,
      edges: edges,
      editorPositions: positions,
    );
  }

  Widget _fallbackInspector(
    MacroEditorNodeViewContext nodeContext,
    String detail,
  ) => MacroEditorNodeInspectorCard(
    title: titleFor(nodeContext.node),
    enabled: nodeContext.state.enabled,
    onRemove: nodeContext.removeNode,
    child: Text(detail),
  );

  Widget _placeholderInspector(
    MacroEditorNodeViewContext nodeContext,
    LightingTargetNodeConfiguration configuration,
  ) {
    final compatibleDevices = nodeContext.state.devices
        .where(
          (device) => _supportsParameters(device, configuration.parameters),
        )
        .toList(growable: false);
    return MacroEditorNodeInspectorCard(
      icon: Icons.device_unknown_outlined,
      title: _templateTransformer.placeholderLabelFor(configuration.targetId),
      enabled: nodeContext.state.enabled,
      onRemove: nodeContext.removeNode,
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: <Widget>[
          const Text(
            'Цей target імпортовано без девайса. Оберіть сумісний девайс, '
            'щоб цей target також надсилав команди.',
          ),
          const SizedBox(height: 12),
          if (compatibleDevices.isEmpty)
            const Text(
              'Немає сумісних девайсів із завантаженим профілем можливостей. '
              'Підключіть девайс і повторіть scan.',
            )
          else
            DropdownButtonFormField<String>(
              key: Key('resolve-template-placeholder-${nodeContext.node.id}'),
              isExpanded: true,
              decoration: const InputDecoration(
                labelText: 'Замінити на девайс',
                border: OutlineInputBorder(),
              ),
              items: compatibleDevices
                  .map(
                    (device) => DropdownMenuItem<String>(
                      value: device.appDeviceId,
                      child: Text(
                        device.displayName,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                  )
                  .toList(growable: false),
              onChanged: nodeContext.state.enabled
                  ? (appDeviceId) {
                      if (appDeviceId == null) return;
                      final device = nodeContext.state.devicesById[appDeviceId];
                      if (device == null ||
                          !_supportsParameters(
                            device,
                            configuration.parameters,
                          )) {
                        return;
                      }
                      nodeContext.replaceNode(
                        _templateTransformer.replacePlaceholderNode(
                          node: nodeContext.node,
                          appDeviceId: device.appDeviceId,
                          deviceName: device.displayName,
                        ),
                      );
                    }
                  : null,
            ),
        ],
      ),
    );
  }

  List<MacroTargetParameter> _parametersForCapabilities(
    DeviceCapabilities? capabilities,
  ) {
    if (capabilities == null) return const <MacroTargetParameter>[];
    return <MacroTargetParameter>[
      if (capabilities.supports(LightingFeature.power, allowInferred: true))
        MacroTargetParameter.power,
      if (capabilities.supports(
        LightingFeature.brightness,
        allowInferred: true,
      ))
        MacroTargetParameter.brightness,
      if (capabilities.supports(LightingFeature.rgb, allowInferred: true) ||
          capabilities.supports(LightingFeature.rgbw, allowInferred: true))
        MacroTargetParameter.color,
    ];
  }

  bool _supportsParameters(
    DebugDevice device,
    Iterable<MacroTargetParameter> parameters,
  ) {
    final supported = _parametersForCapabilities(device.capabilities).toSet();
    return parameters.every(supported.contains);
  }

  Set<LightingFeature> _inputDrivenFeatures(
    MacroEditorNodeViewContext nodeContext,
  ) {
    final outputValues =
        nodeContext.state.runtime?.outputValues ??
        const <String, TriggerValue>{};
    if (outputValues.isEmpty) return const <LightingFeature>{};
    try {
      final configuration = LightingTargetNodeConfiguration.fromNode(
        nodeContext.node,
      );
      final features = <LightingFeature>{};
      for (final parameter in configuration.parameters) {
        final inputPortId = '${nodeContext.node.id}.${parameter.name}';
        final hasValue = nodeContext.state.graph.edges.any(
          (edge) =>
              edge.toPortId == inputPortId &&
              outputValues.containsKey(edge.fromPortId),
        );
        if (!hasValue) continue;
        features.add(switch (parameter) {
          MacroTargetParameter.power => LightingFeature.power,
          MacroTargetParameter.brightness => LightingFeature.brightness,
          MacroTargetParameter.color => LightingFeature.rgb,
        });
      }
      return Set<LightingFeature>.unmodifiable(features);
    } on FormatException {
      return const <LightingFeature>{};
    }
  }

  String? _inputDrivenMessage(Set<LightingFeature> features) {
    if (features.isEmpty) return null;
    final labels = <String>[
      if (features.contains(LightingFeature.power)) 'живлення',
      if (features.contains(LightingFeature.rgb) ||
          features.contains(LightingFeature.rgbw))
        'колір',
      if (features.contains(LightingFeature.brightness)) 'яскравість',
    ];
    return 'Вхід macro зараз має пріоритет: ${labels.join(', ')}.';
  }

  MacroNode _newTargetNode({
    required String id,
    required String targetId,
    required String displayName,
    required List<MacroTargetParameter> parameters,
  }) {
    final configuration = LightingTargetNodeConfiguration(
      targetId: targetId,
      parameters: parameters,
    );
    return MacroNode(
      id: id,
      kind: kind,
      displayName: displayName,
      ports: configuration.portsForNode(id),
      parameters: configuration.toNodeParameters(),
    );
  }

  String _bindingKey(MacroTargetBinding binding) =>
      '${binding.sourcePortId}|${binding.targetId}|${binding.parameter.name}';
}

final class _TargetInput {
  const _TargetInput({required this.targetId, required this.parameter});

  final String targetId;
  final MacroTargetParameter parameter;
}
